before.content:
    if (parts.length != 5 || !"POST".equals(exchange.getRequestMethod())) { status(exchange, 404); return; }
    Map<String, Object> body = readMap(exchange);
    boolean allowed = permissions.answer(parts[4], number(body.get("revision")),
            "allow".equals(body.get("decision")) ? io.github.diodeme.ji.agent.PermissionDecider.Decision.ALLOW
                    : io.github.diodeme.ji.agent.PermissionDecider.Decision.DENY);
    json(exchange, allowed ? 200 : 409, Map.of("resolved", allowed));
}

after.content:
    Map<String, Object> body = readMap(exchange);
    boolean allowed = permissions.answer(parts[4], number(body.get("revision")),
            "allow".equals(body.get("decision")) ? io.github.diodeme.ji.extension.PermissionDecider.Outcome.ALLOW
                    : io.github.diodeme.ji.extension.PermissionDecider.Outcome.DENY);
    json(exchange, allowed ? 200 : 409, Map.of("resolved", allowed));
}
